 detail='蓝丝握住残手后画出他右肩多了一臂、左肩也在变化的形象；这是特定感应结果，未有其他方法验证，不能推出其全身已金刚不坏。'if label=='甲'else'其同伴甲可能出现了多臂变化，但不能把这一线索直接复制给乙，更不能凭两人同处一室就认定身体特征完全相同。'
 bio='研究员'+label+'与另一名不肯公开身世的专家一同进入秘密研究所，凭实际解决生命研究难题的能力获得信任。他们拒绝说明姓名，只被称为甲、乙；所长尊重保密，让二人独立工作。看到从天头派秘藏盗来的水晶状元胎时，两人异常兴奋，要求设备与时间，开始隔绝外界的实验，后来在研究室爆炸中死亡。' +detail+'卫斯理和温宝裕据此提出，两人或许是另一类外星人，觊觎元胎所属者的身体秘密，爆炸可能是对方阻止研究的行动。但小说明确把这一解释称为假设，不能替它补成已确认的星球、族群战争和远程爆破法术。卡片保留其出色研究能力、保密习惯与对未知生命的强烈兴趣；跨世界恢复行动须声明改编，携带的器材也须另行提供，不自动带回已经炸毁的数据。其伦理立场可以通过对实验对象与风险的当下选择表现，不以神秘身份预设绝对善恶。'
 c=human(key,'研究员'+label+'（元胎实验）',bio,'《爆炸》在秘密研究室事故中死亡；外星身份与致死机制仍属假设。','生命研究专长和实验操作；人体变异与元胎功能未获得完整验证。','追索特殊生命形式的秘密，保留自己的身份和研究自主。',[('得到罕见生命材料','有设备和研究时间','高度专注并要求独立实验。'),('外界追问身世','认为公开会妨碍研究','倾向保密，须面对信任与责任的代价。'),('实验显示无法解释的变异','身体或设施已出现风险','在继续、求助与中止之间重新选择，不能预先保证安全。')],[ev(109,2588,2628,'入所和研究'),ev(109,2649,2671,'残手感应'),ev(109,2684,2723,'明确假设范围')],stats=(1,0,2,3,1,2),roles=['谜案核心人物'],dead=True)
 c['confidence']='low';c['rating_input']['rating_confidence']='low';c['uncertainties']=['外星身份、元胎原主及爆炸原因均未确认。']
